-- 外部 API 配置管理：Platform 注册数据（2026-10-13 阶段 3 评审稿）
-- 目标库：Platform Support 业务库；手工执行需单独授权，应用启动不会执行。
-- 344 行 INSERT；0 UPDATE / DELETE；不新增 Gateway Target，不改表结构。
-- 新路由与菜单资源为 DISABLED，PLATFORM_ADMIN 授权为 REVOKED；激活另行处理。
-- 执行前：把 @plt_ext_operator 设为已批准的真实 Operations 账号 ID；按 README 预检，在同一交互连接中执行，不使用 --force。
-- 本文件不含 COMMIT：核对插入行数与 ID 后手工 COMMIT，任何不符则 ROLLBACK。
SET @plt_ext_time=UTC_TIMESTAMP(6);
SET @plt_ext_target=(SELECT target_id FROM t_gateway_target WHERE target_service_code='operations-console-bff' AND channel='OPERATIONS' AND status='ACTIVE');
SET @plt_ext_admin=(SELECT role_id FROM t_role WHERE role_code='PLATFORM_ADMIN' AND scope_key='PLATFORM' AND system_role=1 AND status='ACTIVE');
SELECT @plt_ext_operator operator_id,@plt_ext_target target_id,@plt_ext_admin admin_role_id;
-- 上面三个值任一为空时停止，不进入事务。
START TRANSACTION;








